// Shared native schema/queue/item/budget/publication adapters precede this file.
// The actual planner and actual AddStaticNativePrefix registration are composed.
class StaticNativeModel{internal ItemStack[] Output;internal RecipeQueueItem[] Queue;}
static class RebirthProductiveEarnedNativeBody{
 internal static bool TryMeasure(byte[] bytes,int offset,out long graph,out long scratch){graph=scratch=64;return bytes!=null;}
 internal static bool TryRead(byte[] bytes,int offset,out StaticNativeModel model,out ulong clock){var state=RebirthCamperStationSnapshot.Restore(Guid.Empty,new ItemStack(),bytes);model=new StaticNativeModel{Output=state.Output,Queue=state.Queue};clock=0;return true;}
 internal static byte[] Encode(StaticNativeModel model,ulong clock,out int offset){offset=0;var state=new RebirthCamperStationState{Revision=0,Queue=model.Queue};state.RawOutput(model.Output);return RebirthCamperStationSnapshot.Capture(Guid.Empty,state);}
 internal static byte[] Current(RebirthCamperStationState state){int offset;return Encode(new StaticNativeModel{Output=state.Output,Queue=state.Queue},0,out offset);}}
public static class RebirthRecipeOutputIntegration{
 internal sealed class MillingNativeSource{internal byte[] Body;internal static bool Loaded=true;internal static RebirthCamperStationState Station;internal bool Current()=>Loaded&&Body.SequenceEqual(RebirthProductiveEarnedNativeBody.Current(Station));internal static MillingNativeSource Register(RebirthCookingMillingPublication.StaticSourcePurpose source,byte[] body,int elapsed)=>new MillingNativeSource{Body=body.ToArray()};}}
internal static partial class RebirthCookingMillingPublication{
 internal class StaticSourcePurpose{internal byte[] Intent=new byte[]{9},Before,Output,QueueAfter;internal int BeforeOffset,Index;internal Recipe Recipe;internal string Birth="native-birth";internal IDisposable Memory;internal readonly List<StaticNativePrefix> Prefixes=new List<StaticNativePrefix>();}
 internal class StaticNativePrefix{internal int Step,Elapsed;internal byte[] Body;internal RebirthRecipeOutputIntegration.MillingNativeSource Native;}
 static byte[] Queue(RecipeQueueItem[] rows){using(var memory=new MemoryStream())using(var writer=new BinaryWriter(memory)){writer.Write(rows.Length);foreach(var row in rows)row.Write(writer);writer.Flush();return memory.ToArray();}}
 static RecipeQueueItem[] ReadMobileMillingQueue(byte[] bytes){using(var stream=new MemoryStream(bytes))using(var reader=new PooledBinaryReader()){reader.SetBaseStream(stream);var rows=new RecipeQueueItem[reader.ReadInt32()];for(int i=0;i<rows.Length;i++){rows[i]=new RecipeQueueItem();rows[i].Read(reader);}return rows;}}
 // ACTUAL_STATIC_NATIVE_PREFIX
 static int checks;static RebirthCamperStationState station;static StaticSourcePurpose source;
 static void Need(bool value,string name){checks++;if(!value)throw new Exception(name);}
 static void Fresh(){station=new RebirthCamperStationState();var old=station.Queue[0];source=new StaticSourcePurpose{Before=RebirthProductiveEarnedNativeBody.Current(station),Output=new byte[]{37},QueueAfter=Queue(new[]{new RecipeQueueItem{StartingEntityId=old.StartingEntityId,Quality=old.Quality,OneItemCraftTime=old.OneItemCraftTime}})};RebirthProductiveEarnedObservationBudget.TryRetainDetached(65536,out source.Memory);RebirthRecipeOutputIntegration.MillingNativeSource.Station=station;RebirthRecipeOutputIntegration.MillingNativeSource.Loaded=true;PrepareStaticNativePrefixes(source);}
 public static void Main(){for(int step=0;step<=5;step++){Fresh();Need(station.OutputSetters==0&&station.Queue[0].Recipe!=null,"detached planner mutated actual native source");var row=station.Queue[0];if(step>=1)station.Output=new[]{new ItemStack{Value=37}};if(step>=2)row.Multiplier=0;if(step>=3)row.Recipe=null;if(step>=4)row.IsCrafting=false;if(step>=5)row.CraftingTimeLeft=0;var matches=source.Prefixes.Where(value=>value.Native.Current()).ToArray();Need(matches.Length==1&&matches[0].Step==step,"actual prefix planner selected wrong full native stage "+step);}Fresh();station.Output[0].Value=99;Need(!source.Prefixes.Any(value=>value.Native.Current()),"foreign full native output selected a prefix");Fresh();RebirthRecipeOutputIntegration.MillingNativeSource.Loaded=false;Need(!source.Prefixes.Any(value=>value.Native.Current()),"missing actual native load selected a prefix");Fresh();source.Prefixes.Clear();var invalid=ReadMobileMillingQueue(source.QueueAfter);invalid[0].StartingEntityId++;source.QueueAfter=Queue(invalid);PrepareStaticNativePrefixes(source);Need(source.Prefixes.Count==0,"wrong queue owner produced native continuation");Console.WriteLine("PASS "+checks+" actual static source prefix planner assertions; schema/native execution are adapters");}
}
